"""Exact differentiation and definite-integral checks; requires SymPy."""
import argparse,json
from pathlib import Path
import sympy as s
parser=argparse.ArgumentParser();parser.add_argument('--output',type=Path,required=True);args=parser.parse_args()
x=s.symbols('x',positive=True);P,R,A,B,M,N=s.symbols('P R A B M N');Q=s.Rational;checks=[]
def ck(label,actual,expected):
 ok=s.simplify(actual-expected)==0
 checks.append({'check':label,'passed':bool(ok)})
 if not ok:raise AssertionError((label,actual,expected))
def primitive(label,f,F):ck(label+' differentiated antiderivative',s.diff(F,x),f)
def integral(label,f,a,b,value):ck(label,s.integrate(f,(x,a,b)),value)
for label,f,F in [('1.1a',9*x*x,3*x**3),('1.1b',12*x**-3,-6*x**-2),('1.1c',6*x**Q(5,2),Q(12,7)*x**Q(7,2)),('1.1d',25,25*x),('1.2a',s.sqrt(x),Q(2,3)*x**Q(3,2)),('1.2b',3*x**-Q(1,3),Q(9,2)*x**Q(2,3)),('1.2c',5*x**Q(1,4),4*x**Q(5,4)),('1.2d',-1/(6*s.sqrt(x)),-s.sqrt(x)/3),('1.3a',x**4+x**3-5*x+6,x**5/5+x**4/4-5*x*x/2+6*x),('1.3b',4*x*x+x**-2/3-5*x**-3,Q(4,3)*x**3-x**-1/3+Q(5,2)*x**-2),('1.3c',3*x**-Q(1,4)-2*x**-Q(3,4),4*x**Q(3,4)-8*x**Q(1,4)),('1.4',(4*x+3)**2,Q(16,3)*x**3+12*x*x+9*x),('1.5',(3*x-5)**2,3*x**3-15*x*x+25*x),('1.6',(1-3*x)**2,x-3*x*x+3*x**3),('1.7',(2-5*x)**4,16*x-80*x*x+200*x**3-250*x**4+125*x**5),('1.8',(4-2*s.sqrt(x))**2,16*x-Q(32,3)*x**Q(3,2)+2*x*x),('2.1a',x**4,x**5/5),('2.1b',-7*x**6,-x**7),('2.1c',4*x**-2,-4*x**-1),('2.2a',5*x*x+9*x**-3,Q(5,3)*x**3-Q(9,2)*x**-2),('2.2b',Q(3,4)*x**5-4*x**-5+8*x,x**6/8+x**-4+4*x*x),('2.2c',4*x**Q(3,2)-10*x**-Q(3,2),Q(8,5)*x**Q(5,2)+20*x**-Q(1,2)),('2.3a',(6-5*s.sqrt(x))**2,36*x-40*x**Q(3,2)+Q(25,2)*x*x),('2.3b',(3*x-2)**2/s.sqrt(x),Q(18,5)*x**Q(5,2)-8*x**Q(3,2)+8*s.sqrt(x)),('2.3c',(5-7*x**3+4*x**-Q(3,2))/x**2,-5/x-Q(7,2)*x*x-Q(8,5)*x**-Q(5,2)),('2.4a',P/s.sqrt(x)-R*x**Q(3,2),2*P*s.sqrt(x)-Q(2,5)*R*x**Q(5,2)),('2.4b',A/x**3+B/x**5,-A/(2*x*x)-B/(4*x**4)),('2.4c',M*x**Q(1,3)-N*x**Q(3,4),Q(3,4)*M*x**Q(4,3)-Q(4,7)*N*x**Q(7,4)),('2.5',(6*x**Q(1,5)-5)**2,Q(180,7)*x**Q(7,5)-50*x**Q(6,5)+25*x),('2.6',3*x**3-7*s.sqrt(x)+4*x**-Q(1,3)-2*x**-2,Q(3,4)*x**4-Q(14,3)*x**Q(3,2)+6*x**Q(2,3)+2/x),('2.7',6*x*x+8*x**-5,2*x**3-2*x**-4),('exam6',9*x**Q(2,3)+4/x**2-3*x**3+2,Q(27,5)*x**Q(5,3)-4/x-Q(3,4)*x**4+2*x)]:primitive(label,f,F)
ck('1.9 expansion',s.series((3-2*x)**8,x,0,3).removeO(),6561-34992*x+81648*x*x)
ck('2.8 expansion',s.series((1+2*x)*(4-3*x)**8,x,0,3).removeO(),65536-262144*x+245760*x*x)
for label,f,F,v,y in [('3.1a',4*x**3-10*x*x,x**4-Q(10,3)*x**3+15,3,6),('3.1b',5/s.sqrt(x)+x*x/2,10*s.sqrt(x)+x**3/6-Q(1973,3),16,65),('3.2a',(3-x*x)/x**4,-x**-3+x**-1+4,-1,4),('3.2b',(x-5)**2,x**3/3-5*x*x+25*x-Q(44,3),2,18),('3.3',8/s.sqrt(x)-4*s.sqrt(x),16*s.sqrt(x)-Q(8,3)*x**Q(3,2)-6,9,-30),('3.4',10-6*x-4*x*x,10*x-3*x*x-Q(4,3)*x**3+18,3,-15),('3.5',(5*s.sqrt(x)-3*x**Q(3,2))/x**2,-10*x**-Q(1,2)-6*s.sqrt(x)+24,4,7),('3.6',6*x-4*x**-Q(1,3),3*x*x-6*x**Q(2,3)-56,8,112),('3.7',(1-5*x)**3/x**Q(3,2),-2*x**-Q(1,2)-30*x**Q(1,2)+50*x**Q(3,2)-50*x**Q(5,2)+8,1,-24),('3.8',Q(3,2)*x*x-1/(4*s.sqrt(x)),x**3/2-s.sqrt(x)/2-41,4,-10),('setA bronze',(-5*x*x+7*x**Q(2,3))/s.sqrt(x),-2*x**Q(5,2)+6*x**Q(7,6)-14,1,-10),('setA silver',(1-2*x**Q(1,3))**3,x-Q(9,2)*x**Q(4,3)+Q(36,5)*x**Q(5,3)-4*x*x+Q(568,5),8,24),('setA gold',3*x*x-5*x+8/x**2,x**3-Q(5,2)*x*x-8/x+17,-4,-85)]:primitive(label,f,F);ck(label+' specified point',F.subs(x,v),y)
ck('setA gold other point',(x**3-Q(5,2)*x*x-8/x+17).subs(x,2),11)
for label,f,a,b,value in [('4.1a',x*x,2,10,Q(992,3)),('4.1b',6*x**Q(1,3),1,8,Q(135,2)),('4.1c',4*x**-3,2,4,Q(3,8)),('4.1d',5/s.sqrt(x),4,9,10),('4.2a',18*x-4/x**3,1,2,Q(51,2)),('4.2b',(14*x**3-5*x*x)/s.sqrt(x),1,4,446),('4.2c',(2*s.sqrt(x)-6/x)**2,1,36,2385),('4.3',5/x**2-3/x**4,1,2,Q(13,8)),('4.4',2/x**2+4*s.sqrt(x),1,16,Q(1359,8)),('4.5',Q(8,3)*x**3-6/x**2-2/s.sqrt(x),1,4,Q(323,2)),('4.6',9*s.sqrt(x),4,25,702),('4.7',(2*x**Q(1,3)-x**-Q(1,3)/2)**2,1,8,Q(1223,20)),('4.8',-9*s.sqrt(x),4,9,-114),('5.1',-x**3-x*x+x+1,-1,1,Q(4,3)),('5.2',x*x-7*x+10,-1,2,Q(45,2)),('5.3',5*x*x+2/x**3-5,Q(1,2),2,Q(75,8)),('5.4 full diagram',12+4*x-x*x,-2,6,Q(256,3)),('5.4 stated domain',12+4*x-x*x,0,6,72),('5.5',-(x-1)**2*(x-4),1,4,Q(27,4)),('5.6',8*s.sqrt(x)-x*x,0,4,Q(64,3)),('5.7',6*x*x-12*x+9,0,3,27),('6.1',-(x*x-x-6),-2,3,Q(125,6)),('6.2',-(x+1)*(x-2)*(x-4),2,4,Q(16,3)),('6.3a',x**3-5*x*x+6*x,0,2,Q(8,3)),('6.3b',-x**3+5*x*x-6*x,2,3,Q(5,12)),('6.4',8*s.sqrt(x)-x*x,0,4,Q(64,3)),('6.5',-x*x/2+13*x/2-15,3,10,Q(343,12)),('6.6 left',x*(x+4)*(x-1),-4,0,32),('6.6 right',-x*(x+4)*(x-1),0,1,Q(3,4)),('6.7 left',x**3+6*x*x-4*x-24,-6,-2,64),('6.7 right',-x**3-6*x*x+4*x+24,-2,2,64),('7.1 under',x*x/4+2,-4,4,Q(80,3)),('7.1 between',4-x*x/4,-4,4,Q(64,3)),('7.2 under',-x*x+4*x,1,4,9),('7.2 between',-x*x+5*x-4,1,4,Q(9,2)),('7.3 under',4*s.sqrt(x)-x**Q(3,2)/2+2,1,9,Q(554,15)),('7.3 between',4*s.sqrt(x)-x**Q(3,2)/2+2-(49-5*x)/8,1,9,Q(194,15)),('7.4',-x*x/2+5*x-Q(21,2),3,7,Q(16,3)),('7.5',x*x*(x-4)**2-7*x-2,1,2,Q(31,30)),('7.6',(21-5*x)/4-4/x**2,1,4,Q(27,8)),('7.7',(-x**3-2*x*x+25*x+50)/3,-2,5,Q(4459,36)),('setB bronze',8-x*x/2,-4,4,Q(128,3)),('setB silver',4-x*x,-2,2,Q(32,3)),('setB gold BC',-x**3-2*x*x+x+2,-1,1,Q(8,3)),('setB gold excluded AB',x**3+2*x*x-x-2,-2,-1,Q(5,12)),('exam8',(4-3*x)**3,Q(1,2),1,Q(203,64)),('exam26',8/s.sqrt(x),9,25,32),('exam44',-x*x+x+2,-1,2,Q(9,2)),('exam53',-x**Q(3,2)-2*x+8*s.sqrt(x),0,4,Q(208,15)),('exam79',4*x**Q(3,2)-x**3/2,0,4,Q(96,5))]:integral(label,f,a,b,value)
for label,F,v,result in [('exam79 derivative',6*s.sqrt(x)-Q(3,2)*x*x,16**Q(1,3),0),('exam79 maximum',4*x**Q(3,2)-x**3/2,16**Q(1,3),8),('exam79 root',4*x**Q(3,2)-x**3/2,4,0),('7.6 C line',(21-5*x)/4,4,Q(1,4)),('7.6 C curve',4/x**2,4,Q(1,4)),('7.7 D curve',(-x**3-2*x*x+16*x+32)/3,5,-21),('7.5 P curve',x*x*(x-4)**2,1,9),('7.5 Q curve',x*x*(x-4)**2,2,16)]:ck(label,F.subs(x,v),result)
args.output.write_text(json.dumps(checks,indent=2)+'\n');print(len(checks),'exact checks passed')
